    page_meta: PageMeta = strawberry.field(description="Metadata to aid in pagination.")


@strawberry.type
class Query:
    @strawberry.field(description="Get a list of users.")
    def get_users(self) -> UserResponse: ...


schema = strawberry.Schema(query=Query)
