diff --git a/ui-v2/src/components/deployments/deployment-tags-select.stories.tsx b/ui-v2/src/components/deployments/deployment-tags-select.stories.tsx
--- a/ui-v2/src/components/deployments/deployment-tags-select.stories.tsx
+++ b/ui-v2/src/components/deployments/deployment-tags-select.stories.tsx
@@ -0,0 +1,49 @@
+import type { Meta, StoryObj } from "@storybook/react";
+import { buildApiUrl } from "@tests/utils/handlers";
+import { HttpResponse, http } from "msw";
+import { type ComponentProps, useState } from "react";
+import { createFakeDeployment } from "@/mocks";
+import { reactQueryDecorator } from "@/storybook/utils";
+import { DeploymentTagsSelect } from "./deployment-tags-select";
+
+const MOCK_DEPLOYMENTS = [
+	createFakeDeployment({ tags: ["production", "team-a"] }),
+	createFakeDeployment({ tags: ["staging", "team-b"] }),
+	createFakeDeployment({ tags: ["nightly", "production"] }),
+];
+
+export default {
+	title: "Components/Deployments/DeploymentTagsSelect",
+	component: DeploymentTagsSelect,
+	decorators: [reactQueryDecorator],
+	args: { value: [] },
+	parameters: {
+		msw: {
+			handlers: [
+				http.post(buildApiUrl("/deployments/filter"), () =>
+					HttpResponse.json(MOCK_DEPLOYMENTS),
+				),
+			],
+		},
+	},
+	// To control the selected tags in Stories via useState()
+	render: function Render({
+		value,
+		...args
+	}: ComponentProps<typeof DeploymentTagsSelect>) {
+		const [tags, setTags] = useState<string[]>(value ?? []);
+		return (
+			<div className="w-72">
+				<DeploymentTagsSelect {...args} value={tags} onChange={setTags} />
+			</div>
+		);
+	},
+} satisfies Meta<typeof DeploymentTagsSelect>;
+
+type Story = StoryObj<typeof DeploymentTagsSelect>;
+
+export const Default: Story = {};
+
+export const WithSelectedTags: Story = {
+	args: { value: ["production"] },
+};

diff --git a/ui-v2/src/components/deployments/deployment-tags-select.test.tsx b/ui-v2/src/components/deployments/deployment-tags-select.test.tsx
--- a/ui-v2/src/components/deployments/deployment-tags-select.test.tsx
+++ b/ui-v2/src/components/deployments/deployment-tags-select.test.tsx
@@ -0,0 +1,83 @@
+import { render, screen, within } from "@testing-library/react";
+import userEvent from "@testing-library/user-event";
+import { buildApiUrl, createWrapper, server } from "@tests/utils";
+import { mockPointerEvents } from "@tests/utils/browser";
+import { HttpResponse, http } from "msw";
+import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
+import { createFakeDeployment } from "@/mocks";
+import { DeploymentTagsSelect } from "./deployment-tags-select";
+
+beforeAll(() => {
+	mockPointerEvents();
+});
+
+const mockDeploymentsAPI = (tags: string[][]) => {
+	server.use(
+		http.post(buildApiUrl("/deployments/filter"), () =>
+			HttpResponse.json(
+				tags.map((deploymentTags) =>
+					createFakeDeployment({ tags: deploymentTags }),
+				),
+			),
+		),
+	);
+};
+
+describe("DeploymentTagsSelect", () => {
+	beforeEach(() => {
+		mockDeploymentsAPI([
+			["production", "team-b"],
+			["nightly", "production"],
+			[],
+		]);
+	});
+
+	const openSelect = async (user: ReturnType<typeof userEvent.setup>) => {
+		await user.click(screen.getByRole("button", { name: "Filter by tags" }));
+	};
+
+	it("suggests the tags of existing deployments, deduplicated and sorted", async () => {
+		const user = userEvent.setup();
+		render(<DeploymentTagsSelect value={[]} onChange={vi.fn()} />, {
+			wrapper: createWrapper(),
+		});
+
+		await openSelect(user);
+
+		const listbox = await screen.findByRole("listbox");
+		const options = await within(listbox).findAllByRole("option");
+		expect(options.map((option) => option.textContent)).toEqual([
+			"nightly",
+			"production",
+			"team-b",
+		]);
+	});
+
+	it("adds a suggested tag to the selection", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(<DeploymentTagsSelect value={["nightly"]} onChange={onChange} />, {
+			wrapper: createWrapper(),
+		});
+
+		await openSelect(user);
+		const listbox = await screen.findByRole("listbox");
+		await user.click(await within(listbox).findByText("production"));
+
+		expect(onChange).toHaveBeenCalledWith(["nightly", "production"]);
+	});
+
+	it("adds a tag that no deployment uses", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(<DeploymentTagsSelect value={[]} onChange={onChange} />, {
+			wrapper: createWrapper(),
+		});
+
+		await openSelect(user);
+		await user.type(screen.getByRole("combobox"), "unknown-tag");
+		await user.keyboard("{Enter}");
+
+		expect(onChange).toHaveBeenCalledWith(["unknown-tag"]);
+	});
+});

diff --git a/ui-v2/src/components/deployments/deployment-tags-select.tsx b/ui-v2/src/components/deployments/deployment-tags-select.tsx
--- a/ui-v2/src/components/deployments/deployment-tags-select.tsx
+++ b/ui-v2/src/components/deployments/deployment-tags-select.tsx
@@ -0,0 +1,52 @@
+import { useQuery } from "@tanstack/react-query";
+import { useMemo } from "react";
+import { buildFilterDeploymentsQuery } from "@/api/deployments";
+import { TagsSelect } from "@/components/ui/tags-select";
+
+// Stable filter so the query key does not change between renders. Suggestions
+// come from the unfiltered set of deployments, like the legacy UI. The request
+// gives no limit, because the server rejects a limit that is more than
+// PREFECT_SERVER_API_DEFAULT_LIMIT.
+const SUGGESTIONS_FILTER = {
+	offset: 0,
+	sort: "NAME_ASC",
+} as const;
+
+type DeploymentTagsSelectProps = {
+	value?: string[];
+	onChange?: (tags: string[]) => void;
+	placeholder?: string;
+	id?: string;
+};
+
+export function DeploymentTagsSelect({
+	value = [],
+	onChange,
+	placeholder = "Filter by tags",
+	id,
+}: DeploymentTagsSelectProps) {
+	const { data: deployments } = useQuery(
+		buildFilterDeploymentsQuery(SUGGESTIONS_FILTER),
+	);
+
+	const suggestions = useMemo(() => {
+		const all = new Set<string>();
+		(deployments ?? []).forEach((deployment) => {
+			(deployment.tags ?? []).forEach((tag) => {
+				all.add(tag);
+			});
+		});
+		return Array.from(all).sort((a, b) => a.localeCompare(b));
+	}, [deployments]);
+
+	return (
+		<TagsSelect
+			aria-label={placeholder}
+			id={id}
+			onChange={onChange}
+			placeholder={placeholder}
+			suggestions={suggestions}
+			value={value}
+		/>
+	);
+}

