@@ -0,0 +1,46 @@
+import type { Meta, StoryObj } from "@storybook/react";
+import { type ComponentProps, useState } from "react";
+import { TagsSelect } from "./tags-select";
+
+const SUGGESTIONS = [
+	"nightly",
+	"production",
+	"staging",
+	"team-a",
+	"team-b",
+] as const;
+
+export default {
+	title: "UI/TagsSelect",
+	component: TagsSelect,
+	args: {
+		suggestions: [...SUGGESTIONS],
+		value: [],
+	},
+	// To control the selected tags in Stories via useState()
+	render: function Render({
+		value,
+		...args
+	}: ComponentProps<typeof TagsSelect>) {
+		const [tags, setTags] = useState<string[]>(value ?? []);
+		return (
+			<div className="w-72">
+				<TagsSelect {...args} value={tags} onChange={setTags} />
+			</div>
+		);
+	},
+} satisfies Meta<typeof TagsSelect>;
+
+type Story = StoryObj<typeof TagsSelect>;
+
+export const Default: Story = {
+	args: { placeholder: "Filter by tags" },
+};
+
+export const WithSelectedTags: Story = {
+	args: { value: ["production", "team-a"] },
+};
+
+export const WithoutSuggestions: Story = {
+	args: { suggestions: [] },
+};

diff --git a/ui-v2/src/components/ui/tags-select/tags-select.test.tsx b/ui-v2/src/components/ui/tags-select/tags-select.test.tsx
--- a/ui-v2/src/components/ui/tags-select/tags-select.test.tsx
+++ b/ui-v2/src/components/ui/tags-select/tags-select.test.tsx
@@ -0,0 +1,184 @@
+import { render, screen, waitFor, within } from "@testing-library/react";
+import userEvent from "@testing-library/user-event";
+import { mockPointerEvents } from "@tests/utils/browser";
+import { beforeAll, describe, expect, it, vi } from "vitest";
+import { TagsSelect } from "./tags-select";
+
+const SUGGESTIONS = ["alpha", "beta", "prod"];
+
+beforeAll(() => {
+	mockPointerEvents();
+});
+
+describe("TagsSelect", () => {
+	const openSelect = async (user: ReturnType<typeof userEvent.setup>) => {
+		await user.click(screen.getByRole("button", { name: /tags/i }));
+	};
+
+	it("shows the placeholder when no tags are selected", () => {
+		render(
+			<TagsSelect
+				suggestions={SUGGESTIONS}
+				value={[]}
+				onChange={vi.fn()}
+				placeholder="All tags"
+			/>,
+		);
+
+		expect(screen.getByText("All tags")).toBeInTheDocument();
+	});
+
+	it("shows selected tags in the trigger", () => {
+		render(
+			<TagsSelect
+				suggestions={SUGGESTIONS}
+				value={["alpha", "beta"]}
+				onChange={vi.fn()}
+			/>,
+		);
+
+		expect(screen.getByText("alpha")).toBeInTheDocument();
+		expect(screen.getByText("beta")).toBeInTheDocument();
+	});
+
+	it("lists the suggestions", async () => {
+		const user = userEvent.setup();
+		render(
+			<TagsSelect suggestions={SUGGESTIONS} value={[]} onChange={vi.fn()} />,
+		);
+
+		await openSelect(user);
+
+		const listbox = await screen.findByRole("listbox");
+		for (const suggestion of SUGGESTIONS) {
+			expect(within(listbox).getByText(suggestion)).toBeInTheDocument();
+		}
+	});
+
+	it("selects a suggestion", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(
+			<TagsSelect
+				suggestions={SUGGESTIONS}
+				value={["alpha"]}
+				onChange={onChange}
+			/>,
+		);
+
+		await openSelect(user);
+		const listbox = await screen.findByRole("listbox");
+		await user.click(within(listbox).getByText("prod"));
+
+		expect(onChange).toHaveBeenCalledWith(["alpha", "prod"]);
+	});
+
+	it("filters the suggestions by the search value", async () => {
+		const user = userEvent.setup();
+		render(
+			<TagsSelect suggestions={SUGGESTIONS} value={[]} onChange={vi.fn()} />,
+		);
+
+		await openSelect(user);
+		await user.type(screen.getByRole("combobox"), "al");
+
+		const listbox = await screen.findByRole("listbox");
+		expect(within(listbox).getByText("alpha")).toBeInTheDocument();
+		expect(within(listbox).queryByText("prod")).not.toBeInTheDocument();
+	});
+
+	it("adds a freeform tag on Enter", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(
+			<TagsSelect suggestions={SUGGESTIONS} value={[]} onChange={onChange} />,
+		);
+
+		await openSelect(user);
+		await user.type(screen.getByRole("combobox"), "newtag");
+		await user.keyboard("{Enter}");
+
+		expect(onChange).toHaveBeenCalledWith(["newtag"]);
+	});
+
+	it("adds a tag when typing a trailing comma", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(
+			<TagsSelect suggestions={SUGGESTIONS} value={[]} onChange={onChange} />,
+		);
+
+		await openSelect(user);
+		await user.type(screen.getByRole("combobox"), "temp,");
+
+		await waitFor(() => {
+			expect(onChange).toHaveBeenCalledWith(["temp"]);
+		});
+	});
+
+	it("removes the last tag on Backspace when the search is empty", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(
+			<TagsSelect
+				suggestions={SUGGESTIONS}
+				value={["alpha"]}
+				onChange={onChange}
+			/>,
+		);
+
+		await openSelect(user);
+		await user.keyboard("{Backspace}");
+
+		expect(onChange).toHaveBeenCalledWith([]);
+	});
+
+	it("removes a tag with the remove button", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(
+			<TagsSelect
+				suggestions={SUGGESTIONS}
+				value={["alpha", "beta"]}
+				onChange={onChange}
+			/>,
+		);
+
+		await openSelect(user);
+		await user.click(
+			await screen.findByRole("button", { name: /remove alpha tag/i }),
+		);
+
+		expect(onChange).toHaveBeenCalledWith(["beta"]);
+	});
+
+	it("clears all tags", async () => {
+		const onChange = vi.fn();
+		const user = userEvent.setup();
+		render(
+			<TagsSelect
+				suggestions={SUGGESTIONS}
+				value={["alpha", "beta"]}
+				onChange={onChange}
+			/>,
+		);
+
+		await openSelect(user);
+		const listbox = await screen.findByRole("listbox");
+		await user.click(await within(listbox).findByText(/clear all tags/i));
+
+		expect(onChange).toHaveBeenCalledWith([]);
+	});
+
+	it("does not show 'No tags found' when there are no suggestions", async () => {
+		const user = userEvent.setup();
+		render(<TagsSelect suggestions={[]} value={[]} onChange={vi.fn()} />);
+
+		await openSelect(user);
+
+		const listbox = await screen.findByRole("listbox");
+		expect(
+			within(listbox).queryByText(/no tags found/i),
+		).not.toBeInTheDocument();
+	});
+});

diff --git a/ui-v2/src/components/ui/tags-select/tags-select.tsx b/ui-v2/src/components/ui/tags-select/tags-select.tsx
--- a/ui-v2/src/components/ui/tags-select/tags-select.tsx
+++ b/ui-v2/src/components/ui/tags-select/tags-select.tsx
@@ -0,0 +1,179 @@
+import { useCallback, useEffect, useState } from "react";
+import {
+	Combobox,
+	ComboboxCommandEmtpy,
+	ComboboxCommandGroup,
+	ComboboxCommandInput,
+	ComboboxCommandItem,
+	ComboboxCommandList,
+	ComboboxContent,
+	ComboboxTrigger,
+} from "@/components/ui/combobox";
+import { Icon } from "@/components/ui/icons";
+import { TagBadgeGroup } from "@/components/ui/tag-badge-group";
+
+export type TagsSelectProps = {
+	suggestions: string[];
+	value?: string[];
+	onChange?: (tags: string[]) => void;
+	placeholder?: string;
+	"aria-label"?: string;
+	id?: string;
+};
+
+/**
+ * Combobox that selects tags from a list of suggestions and also accepts
+ * freeform tags. Callers provide the suggestions.
+ */
+export function TagsSelect({
+	suggestions,
+	value = [],
+	onChange,
+	placeholder = "All tags",
+	"aria-label": ariaLabel = "Tags",
+	id,
+}: TagsSelectProps) {
+	const [search, setSearch] = useState("");
+
+	const toggleTag = (tag: string) => {
+		const exists = value.includes(tag);
+		const next = exists ? value.filter((t) => t !== tag) : [...value, tag];
+		onChange?.(next);
+	};
+
+	const addFreeformTag = useCallback(
+		(tag: string) => {
+			if (!tag) return;
+			if (value.includes(tag)) return;
+			onChange?.([...value, tag]);
+		},
+		[onChange, value],
+	);
+
+	// Add on trailing comma for quick entry (matches common tags UX)
+	useEffect(() => {
+		const trimmed = search.trim();
+		if (trimmed.endsWith(",")) {
+			const tag = trimmed.replace(/,+$/, "").trim();
+			if (tag) {
+				addFreeformTag(tag);
+			}
+			setSearch("");
+		}
+	}, [search, addFreeformTag]);
+
+	return (
+		<div className="w-full">
+			<Combobox>
+				<ComboboxTrigger
+					aria-label={ariaLabel}
+					id={id}
+					selected={value.length === 0}
+				>
+					{value.length > 0 ? (
+						<div className="flex items-center gap-1 overflow-hidden">
+							<TagBadgeGroup
+								tags={value}
+								variant="secondary"
+								maxTagsDisplayed={3}
+							/>
+						</div>
+					) : (
+						<span className="text-muted-foreground">{placeholder}</span>
+					)}
+				</ComboboxTrigger>
+				<ComboboxContent>
+					<ComboboxCommandInput
+						value={search}
+						onValueChange={setSearch}
+						placeholder="Search or enter new tag"
+						onKeyDown={(e) => {
+							const query = search.trim();
+							if (e.key === "Enter" && query) {
+								e.preventDefault();
+								addFreeformTag(query);
+								setSearch("");
+							} else if (e.key === "Backspace" && !search && value.length > 0) {
+								onChange?.(value.slice(0, -1));
+							}
+						}}
+					/>
+					<ComboboxCommandList>
+						{suggestions.length > 0 ? (
+							<ComboboxCommandEmtpy>No tags found</ComboboxCommandEmtpy>
+						) : null}
+						<ComboboxCommandGroup>
+							{/* Selected tags with inline remove */}
+							{value.length > 0 && (
+								<div>
+									{value.map((tag) => (
+										<ComboboxCommandItem
+											key={`selected-${tag}`}
+											value={`selected-${tag}`}
+											onSelect={() => toggleTag(tag)}
+											closeOnSelect={false}
+										>
+											<button
+												type="button"
+												aria-label={`Remove ${tag} tag`}
+												className="text-muted-foreground hover:text-foreground"
+												onClick={(ev) => {
+													ev.preventDefault();
+													ev.stopPropagation();
+													onChange?.(value.filter((t) => t !== tag));
+												}}
+											>
+												<Icon id="X" className="size-3" />
+											</button>
+											<span>{tag}</span>
+										</ComboboxCommandItem>
+									))}
+									<ComboboxCommandItem
+										value="__clear__"
+										onSelect={() => onChange?.([])}
+										closeOnSelect={false}
+									>
+										Clear all tags
+									</ComboboxCommandItem>
+								</div>
+							)}
+
+							{/* Add freeform */}
+							{search.trim() && !value.includes(search.trim()) && (
+								<ComboboxCommandItem
+									value={`__add__:${search.trim()}`}
+									onSelect={() => addFreeformTag(search.trim())}
+									closeOnSelect={false}
+								>
+									Add &quot;{search.trim()}&quot;
+								</ComboboxCommandItem>
+							)}
+
+							{/* Suggestions (exclude already selected) */}
+							{suggestions
+								.filter((t) => !value.includes(t))
+								.filter((t) => {
+									const q = search.trim().toLowerCase();
+									if (!q) return true;
+									return t.toLowerCase().includes(q);
+								})
+								.map((tag) => (
+									<ComboboxCommandItem
+										key={tag}
+										value={tag}
+										selected={value.includes(tag)}
+										onSelect={() => toggleTag(tag)}
+										closeOnSelect={false}
+									>
+										{tag}
+									</ComboboxCommandItem>
+								))}
+						</ComboboxCommandGroup>
+					</ComboboxCommandList>
+				</ComboboxContent>
+			</Combobox>
+		</div>
+	);
+}
+
+TagsSelect.displayName = "TagsSelect";", "docs_before_excerpt": "<!-- docs/v3/api-ref/python/prefect-deployments-flow_runs.mdx @ 8396d0cf707213afcd9de41893353b08067edb2c -->
